use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl < T > FreezeLock < T > { # [inline] pub fn new (value : T) -> Self { Self :: with (value , false) } # [inline] pub fn frozen (value : T) -> Self { Self :: with (value , true) } # [inline] pub fn with (value : T , frozen : bool) -> Self { Self { data : UnsafeCell :: new (value) , frozen : AtomicBool :: new (frozen) , lock : RwLock :: new (()) , } } # [doc = " Clones the inner value along with the frozen state."] # [inline] pub fn clone (& self) -> Self where T : Clone , { let lock = self . read () ; Self :: with (lock . clone () , self . is_frozen ()) } # [inline] pub fn is_frozen (& self) -> bool { self . frozen . load (Ordering :: Acquire) } # [doc = " Get the inner value if frozen."] # [inline] pub fn get (& self) -> Option < & T > { if likely (self . frozen . load (Ordering :: Acquire)) { unsafe { Some (& * self . data . get ()) } } else { None } } # [inline] pub fn read (& self) -> FreezeReadGuard < '_ , T > { FreezeReadGuard { _lock_guard : if self . frozen . load (Ordering :: Acquire) { None } else { Some (self . lock . read ()) } , data : unsafe { NonNull :: new_unchecked (self . data . get ()) } , } } # [inline] pub fn borrow (& self) -> FreezeReadGuard < '_ , T > { self . read () } # [inline] # [track_caller] pub fn write (& self) -> FreezeWriteGuard < '_ , T > { self . try_write () . expect ("data should not be frozen if we're still attempting to mutate it") } # [inline] pub fn try_write (& self) -> Option < FreezeWriteGuard < '_ , T > > { let _lock_guard = self . lock . write () ; if self . frozen . load (Ordering :: Relaxed) { None } else { Some (FreezeWriteGuard { _lock_guard , data : unsafe { NonNull :: new_unchecked (self . data . get ()) } , frozen : & self . frozen , marker : PhantomData , }) } } # [inline] pub fn freeze (& self) -> & T { if ! self . frozen . load (Ordering :: Acquire) { let _lock = self . lock . write () ; self . frozen . store (true , Ordering :: Release) ; } unsafe { & * self . data . get () } } }
}